@interface TFAIReferencePreview : UIViewController
@property NSDictionary *entry;
@end
@implementation TFAIReferencePreview
- (void)viewDidLoad{[super viewDidLoad];self.title=self.entry[@"path"]?:@"参考附件";self.view.backgroundColor=UIColor.systemBackgroundColor;UIActivityIndicatorView *spinner=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];spinner.center=self.view.center;spinner.autoresizingMask=UIViewAutoresizingFlexibleLeftMargin|UIViewAutoresizingFlexibleRightMargin|UIViewAutoresizingFlexibleTopMargin|UIViewAutoresizingFlexibleBottomMargin;[self.view addSubview:spinner];[spinner startAnimating];NSDictionary *entry=self.entry;__weak typeof(self) weak=self;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSDictionary *item=TFAIResolveAttachments(@[entry],&error).firstObject;dispatch_async(dispatch_get_main_queue(),^{UIViewController *v=weak;if(!v)return;[spinner removeFromSuperview];if(error){AIAlert(v,@"预览失败",error.localizedDescription);return;}UIView *content;if([item[@"kind"] isEqual:@"image"]){UIImageView *image=[[UIImageView alloc]initWithImage:[UIImage imageWithData:[[NSData alloc]initWithBase64EncodedString:item[@"data"] options:0]]];image.contentMode=UIViewContentModeScaleAspectFit;content=image;}else{UITextView *text=[UITextView new];text.editable=NO;text.font=[UIFont monospacedSystemFontOfSize:14 weight:UIFontWeightRegular];text.text=item[@"directoryGrant"]?@"目录授权 · 只读\n\n发送时只交给 AI 一个目录引用，不复制、不逐个附加，也不上传整个文件夹。AI 按需浏览目录、搜索和读取。读取的片段才会发送给模型服务商。\n\n授权随会话保留；发送后可点击会话中的目录卡片撤销授权。移除待发送卡片会取消此次添加。":item[@"content"];text.backgroundColor=UIColor.systemBackgroundColor;content=text;}content.translatesAutoresizingMaskIntoConstraints=NO;[v.view addSubview:content];[NSLayoutConstraint activateConstraints:@[[content.topAnchor constraintEqualToAnchor:v.view.safeAreaLayoutGuide.topAnchor],[content.bottomAnchor constraintEqualToAnchor:v.view.safeAreaLayoutGuide.bottomAnchor],[content.leadingAnchor constraintEqualToAnchor:v.view.safeAreaLayoutGuide.leadingAnchor constant:12],[content.trailingAnchor constraintEqualToAnchor:v.view.safeAreaLayoutGuide.trailingAnchor constant:-12]]];});});}
@end
UIViewController *TFAIAttachmentPreview(NSDictionary *entry){TFAIReferencePreview *v=[TFAIReferencePreview new];v.entry=entry;return v;}
@interface TFAIReferenceTree : UITableViewController <UISearchResultsUpdating>
@property NSString *root,*source,*prefix;
@property NSArray *files,*filtered;
@property NSMutableSet *selected;
@property UILabel *summary;
@property BOOL loading;
@property(copy) void (^completion)(NSArray *);
@end
@implementation TFAIReferenceTree
- (void)viewDidLoad{[super viewDidLoad];self.title=self.prefix.length?TFAIAttachmentFolderName([self.root stringByAppendingPathComponent:self.prefix]):self.source;BOOL preloaded=self.files!=nil;if(!self.files)self.files=@[];self.filtered=@[];if(!self.selected)self.selected=[NSMutableSet new];self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=62;self.navigationItem.rightBarButtonItems=@[AIBar(@"checkmark",@"添加文件或授权当前文件夹",self,@selector(importSelected))];UISearchController *search=[[UISearchController alloc]initWithSearchResultsController:nil];search.obscuresBackgroundDuringPresentation=NO;search.searchResultsUpdater=self;search.searchBar.placeholder=@"搜索文件或目录路径";self.navigationItem.searchController=search;self.summary=[UILabel new];self.summary.numberOfLines=0;self.summary.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption1];self.summary.textColor=UIColor.secondaryLabelColor;self.summary.textAlignment=NSTextAlignmentCenter;self.summary.frame=CGRectMake(0,0,320,90);self.tableView.tableHeaderView=self.summary;self.summary.text=@"正在读取目录清单…\n仅列出可用文件，尚未读取文件内容";if(preloaded){[self rebuildRows:@""];[self updateSummary];return;}self.loading=YES;self.navigationItem.rightBarButtonItem.enabled=NO;__weak typeof(self) weak=self;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSArray *files=TFAIAttachmentCandidates(weak.root,&error);dispatch_async(dispatch_get_main_queue(),^{weak.loading=NO;weak.files=files?:@[];[weak rebuildRows:@""];[weak updateSummary];[weak.tableView reloadData];if(error)AIAlert(weak,@"目录读取失败",error.localizedDescription);});});}
- (NSArray *)currentFolderPaths{NSString *prefix=self.prefix.length?[self.prefix stringByAppendingString:@"/"]:@"";NSMutableArray *paths=[NSMutableArray new];for(NSDictionary *f in self.files)if(!prefix.length||[f[@"relativePath"] hasPrefix:prefix])[paths addObject:f[@"relativePath"]];return paths;}
- (void)updateSummary{NSUInteger bytes=0;for(NSDictionary *f in self.files)if([self.selected containsObject:f[@"relativePath"]])bytes+=[f[@"bytes"] unsignedIntegerValue];self.summary.text=[NSString stringWithFormat:@"%lu 个可选文件 · 已选 %lu 个 · %.1f KB\n未勾选文件时，✅ 只授权当前目录，不复制或上传文件\ndeb / dylib 在本机解析后按需读取；排除缓存、Git 和凭据",(unsigned long)self.files.count,(unsigned long)self.selected.count,bytes/1024.0];self.navigationItem.rightBarButtonItem.enabled=!self.loading;}
- (void)rebuildRows:(NSString *)query{NSString *prefix=self.prefix.length?[self.prefix stringByAppendingString:@"/"]:@"";NSMutableArray *rows=[NSMutableArray new];NSMutableDictionary *dirs=[NSMutableDictionary new];for(NSDictionary *file in self.files){NSString *path=file[@"relativePath"];if(prefix.length&&![path hasPrefix:prefix])continue;NSString *remaining=[path substringFromIndex:prefix.length];if(query.length){if([remaining localizedCaseInsensitiveContainsString:query])[rows addObject:file];continue;}if([remaining containsString:@"/"]){NSString *dir=[prefix stringByAppendingString:remaining.pathComponents.firstObject];NSMutableDictionary *d=dirs[dir];if(!d){d=[@{@"relativePath":dir,@"directory":@YES,@"bytes":@0,@"count":@0} mutableCopy];dirs[dir]=d;}d[@"bytes"]=@([d[@"bytes"] unsignedLongLongValue]+[file[@"bytes"] unsignedLongLongValue]);d[@"count"]=@([d[@"count"] unsignedIntegerValue]+1);}else[rows addObject:file];}NSArray *folders=[dirs.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [a[@"relativePath"] localizedStandardCompare:b[@"relativePath"]];}];self.filtered=[folders arrayByAddingObjectsFromArray:rows];UILabel *empty=[UILabel new];empty.numberOfLines=0;empty.textAlignment=NSTextAlignmentCenter;empty.font=[UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];empty.textColor=UIColor.secondaryLabelColor;empty.text=query.length?@"没有匹配的文件\n试试文件名或目录路径":@"此目录没有可附加的文件\n缓存及敏感文件已排除";self.tableView.backgroundView=self.filtered.count?nil:empty;}
- (void)toggleFolder{NSString *prefix=self.prefix.length?[self.prefix stringByAppendingString:@"/"]:@"";NSMutableArray *paths=[NSMutableArray new];BOOL all=YES;for(NSDictionary *file in self.files)if(!prefix.length||[file[@"relativePath"] hasPrefix:prefix]){[paths addObject:file[@"relativePath"]];if(![self.selected containsObject:file[@"relativePath"]])all=NO;}if(!all&&[self.selected setByAddingObjectsFromArray:paths].count>80){AIAlert(self,@"文件夹超过选择限制",@"请进入子目录或逐个选择，单次最多 80 个文件。");return;}for(NSString *path in paths)if(all)[self.selected removeObject:path];else[self.selected addObject:path];[self updateSummary];[self.tableView reloadData];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];if(!self.loading){[self rebuildRows:self.navigationItem.searchController.searchBar.text?:@""];[self updateSummary];[self.tableView reloadData];}}
- (void)updateSearchResultsForSearchController:(UISearchController *)s{[self rebuildRows:s.searchBar.text?:@""];[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.filtered.count;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *f=self.filtered[i.row];NSString *path=f[@"relativePath"];if([f[@"directory"] boolValue]){UITableViewCell *folder=AICell(TFAIAttachmentFolderName([self.root stringByAppendingPathComponent:path]),[NSString stringWithFormat:@"%@ 个文件 · %.1f KB · 进入目录，✅ 授权此目录",f[@"count"],[f[@"bytes"] doubleValue]/1024.0],@"folder");folder.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return folder;}UITableViewCell *c=AICell(path.lastPathComponent,[NSString stringWithFormat:@"%@ · %.1f KB · 参考副本",[f[@"media"] isEqual:@"artifact"]?@"产物 · 本机解析":([f[@"media"] isEqual:@"image"]?@"图片":@"文本"),[f[@"bytes"] doubleValue]/1024.0],[f[@"media"] isEqual:@"image"]?@"photo":@"doc.text");c.textLabel.numberOfLines=2;c.accessoryType=[self.selected containsObject:path]?UITableViewCellAccessoryCheckmark:UITableViewCellAccessoryNone;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];NSDictionary *file=self.filtered[i.row];NSString *p=file[@"relativePath"];if([file[@"directory"] boolValue]){TFAIReferenceTree *child=[[TFAIReferenceTree alloc]initWithStyle:UITableViewStyleInsetGrouped];child.root=self.root;child.source=self.source;child.prefix=p;child.files=self.files;child.selected=self.selected;child.completion=self.completion;[self.navigationController pushViewController:child animated:YES];return;}if([self.selected containsObject:p])[self.selected removeObject:p];else if(self.selected.count<80)[self.selected addObject:p];else AIAlert(self,@"已选 80 个文件",@"请取消部分选择后再添加。");[self updateSummary];[t reloadRowsAtIndexPaths:@[i] withRowAnimation:UITableViewRowAnimationNone];}
- (void)importSelected{if(self.loading)return;if(!self.selected.count){NSError *error=nil;NSString *path=self.prefix.length?[self.root stringByAppendingPathComponent:self.prefix]:self.root;NSMutableDictionary *grant=[TFAIAuthorizeDirectory([NSURL fileURLWithPath:path],self.source,&error) mutableCopy];if(grant)grant[@"path"]=TFAIAttachmentFolderName(path);if(!grant){AIAlert(self,@"目录授权失败",error.localizedDescription);return;}void(^completion)(NSArray *)=self.completion;if(self.presentingViewController||self.navigationController.presentingViewController)[self dismissViewControllerAnimated:YES completion:^{if(completion)completion(@[grant]);}];else if(completion)completion(@[grant]);return;}NSArray *chosen=self.selected.allObjects;if(chosen.count>80){AIAlert(self,@"文件夹超过选择限制",@"请进入子文件夹或选择部分文件，单次最多 80 个文件。");return;}self.loading=YES;[self updateSummary];self.summary.text=@"正在复制所选文件到本机参考区…\n文本副本上限 20 MB，AI 按需分段读取；未修改原工程";NSArray *paths=chosen;__weak typeof(self) weak=self;dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSError *error=nil;NSArray *entries=TFAIStageAttachmentFiles(weak.root,paths,weak.source,&error);dispatch_async(dispatch_get_main_queue(),^{weak.loading=NO;[weak updateSummary];if(error){AIAlert(weak,@"导入失败",error.localizedDescription);return;}void(^completion)(NSArray *)=weak.completion;[weak dismissViewControllerAnimated:YES completion:^{if(completion)completion(entries);}];});});}
@end
@interface TFAIReferenceSources : UITableViewController
@property NSArray *sources;
@property(copy) void (^completion)(NSArray *);
@end
@implementation TFAIReferenceSources
- (void)viewDidLoad{[super viewDidLoad];self.title=@"选择参考文件";self.navigationItem.rightBarButtonItem=AIBar(@"xmark",@"关闭附件浏览",self,@selector(close));self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=65;}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.sources.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return @"✅ 授权当前文件夹时只添加一张目录卡片，发送后 AI 可按需列目录、搜索和读取，持续到撤销。单独勾选的文件作为参考副本；均不授予修改权限。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *s=self.sources[i.row];UITableViewCell *c=AICell(s[@"name"],s[@"detail"],@"folder");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];NSDictionary *s=self.sources[i.row];TFAIReferenceTree *v=[[TFAIReferenceTree alloc]initWithStyle:UITableViewStyleInsetGrouped];v.root=s[@"root"];v.source=s[@"name"];v.completion=self.completion;[self.navigationController pushViewController:v animated:YES];}
@end
UIViewController *TFAIAttachmentBrowser(NSString *currentRoot,NSArray *projects,void(^selected)(NSArray *)){NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject.stringByResolvingSymlinksInPath;NSMutableArray *sources=[NSMutableArray new];NSMutableSet *seen=[NSMutableSet new];for(NSDictionary *p in projects){NSString *root=[p[@"root"] isKindOfClass:NSString.class]?[p[@"root"] stringByResolvingSymlinksInPath]:nil;if(![root hasPrefix:[docs stringByAppendingString:@"/"]]||[seen containsObject:root])continue;[seen addObject:root];BOOL current=[root isEqual:currentRoot.stringByResolvingSymlinksInPath];NSDictionary *s=@{@"root":root,@"name":p[@"name"]?:root.lastPathComponent,@"detail":current?@"当前工程 · 选择文件与内部文件夹":@"其他工程 · 作为参考副本"};if(current)[sources insertObject:s atIndex:0];else[sources addObject:s];}if(currentRoot.length&&[currentRoot.stringByResolvingSymlinksInPath hasPrefix:[docs stringByAppendingString:@"/"]]&&![seen containsObject:currentRoot.stringByResolvingSymlinksInPath])[sources insertObject:@{@"root":currentRoot,@"name":currentRoot.lastPathComponent,@"detail":@"当前工程"} atIndex:0];if(currentRoot.length){NSString *saved=[NSUserDefaults.standardUserDefaults stringForKey:[@"StudioBuild-" stringByAppendingString:currentRoot.lastPathComponent]];if(saved.length&&[saved isEqual:saved.lastPathComponent]){NSString *build=[docs stringByAppendingPathComponent:saved];NSData *data=[NSData dataWithContentsOfFile:[build stringByAppendingPathComponent:@".studio-cache-owner.json"]];NSDictionary *owner=data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:nil;if([owner isKindOfClass:NSDictionary.class]&&[owner[@"project"] isKindOfClass:NSString.class]&&[[owner[@"project"] stringByResolvingSymlinksInPath] isEqual:currentRoot.stringByResolvingSymlinksInPath]&&[build.stringByResolvingSymlinksInPath hasPrefix:[docs stringByAppendingString:@"/"]])[sources insertObject:@{@"root":build,@"name":@"当前项目构建结果",@"detail":@"deb、dylib 与构建记录 · 本机只读检查"} atIndex:MIN(1,sources.count)];}}[sources addObject:@{@"root":docs,@"name":@"软件内部文件夹",@"detail":@"Documents 内可用文件 · 排除构建缓存"}];TFAIReferenceSources *v=[[TFAIReferenceSources alloc]initWithStyle:UITableViewStyleInsetGrouped];v.sources=sources;v.completion=selected;return v;}
